<div class="top"><div><h2 style="margin:0">Customers</h2><span class="muted"><?= count($rows) ?> shown</span></div><?php if (can('customers.manage')): ?><a class="btn" href="/staff/customers/new">+ New customer</a><?php endif; ?></div>
<form class="filters" method="get"><input name="q" value="<?= e($s) ?>" placeholder="Search name, email, phone, GSTIN"><button class="btn alt sm">Search</button></form>
<div class="card"><div class="tw"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>GSTIN</th><th class="right">Orders</th><th class="right">Invoiced</th><th class="right">Owed</th></tr>
<?php foreach ($rows as $r): ?><tr><td><a href="/staff/customers/<?= (int) $r['id'] ?>"><?= e($r['name']) ?></a></td><td><?= str_ends_with($r['email'], '@walkin.invalid') ? '<span class="muted">—</span>' : e($r['email']) ?></td><td><?= e((string) $r['phone']) ?></td><td><?= e((string) $r['gstin']) ?></td><td class="right"><?= (int) $r['orders'] ?></td><td class="right"><?= e(money($r['invoiced'])) ?></td><td class="right <?= $r['owed'] > 0 ? 'overdue' : '' ?>"><?= $r['owed'] > 0 ? e(money($r['owed'])) : '—' ?></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="7" class="muted">No customers found.</td></tr><?php endif; ?></table></div></div>
